import { useEffect, useState } from "react";
import { type AttachmentHandlerOpts } from "@sierra/web";

export type SecretRefreshAttachmentPayload = {
    type: "secret_refresh";
    secretName: string;
    initialDelaySeconds?: number;
    retryConfig?: {
        maxAttempts?: number;
        retryDelaySeconds?: number;
        maxDelaySeconds?: number;
    };
};

export function SecretRefresh({
    opts,
    data,
}: {
    opts: AttachmentHandlerOpts;
    data: SecretRefreshAttachmentPayload;
}): JSX.Element | null {
    const refreshSecret = opts.refreshSecret;
    const sendMessage = opts.sendMessage;
    const [cancelled, setCancelled] = useState(false);
    useEffect(() => {
        let currentTimeout: number | null = null;
        const intialDelaySeconds = data.initialDelaySeconds ?? 0;
        const maxAttempts = data.retryConfig?.maxAttempts ?? 1;
        const retryDelaySeconds = data.retryConfig?.retryDelaySeconds ?? 5;
        const maxDelaySeconds = data.retryConfig?.maxDelaySeconds ?? 10;

        // Helper to clear any scheduled timeouts.
        const clearTimer = () => {
            if (currentTimeout !== null) {
                clearTimeout(currentTimeout);
            }
        };

        /**
         * Attempts to call opts.refreshSecret.
         *
         * @param attemptNumber – current attempt count (starting at 1).
         * @param delay – the delay (in ms) to use for the next attempt.
         */
        const attemptRefresh = (attemptNumber: number, delay: number) => {
            if (cancelled) {
                return;
            }
            // Call the refreshSecret function (expects a Promise<boolean>)
            refreshSecret(data.secretName)
                .then((result: boolean) => {
                    if (result) {
                        sendMessage("", [
                            {
                                type: "custom",
                                data: JSON.stringify({
                                    type: "secret_refreshed",
                                    secretName: data.secretName,
                                }),
                            },
                        ]);
                        setCancelled(true);
                    }
                    if (!result && attemptNumber < maxAttempts) {
                        scheduleRetry(attemptNumber + 1, delay);
                    }
                })
                .catch(() => {
                    if (attemptNumber < maxAttempts) {
                        scheduleRetry(attemptNumber + 1, delay);
                    }
                });
        };

        /**
         * Schedules a retry attempt.
         *
         * @param nextAttempt – the next attempt count.
         * @param currentDelay – the delay used in the previous attempt
         */
        const scheduleRetry = (nextAttempt: number, currentDelay: number) => {
            if (cancelled) {
                return;
            }
            // Increase delay exponentially, capped at maxDelaySeconds.
            const nextDelay = Math.min(currentDelay * 2, maxDelaySeconds * 1000);
            currentTimeout = window.setTimeout(() => {
                attemptRefresh(nextAttempt, nextDelay);
            }, currentDelay);
        };

        // Start after initial delay.
        currentTimeout = window.setTimeout(() => {
            attemptRefresh(1, retryDelaySeconds * 1000);
        }, intialDelaySeconds * 1000);

        return () => {
            clearTimer();
        };
    }, [data, refreshSecret, sendMessage, cancelled]);

    // This component does not render anything.
    return null;
}
